{"name": "solve_frustum_volume", "code": "import math

def solve(inputs: dict) -> float:
    RADIUS_BOTTOM = inputs['RADIUS_BOTTOM']
    RADIUS_TOP = inputs['RADIUS_TOP']
    HEIGHT = inputs['HEIGHT']
    return (1/3) * math.pi * HEIGHT * (RADIUS_BOTTOM**2 + RADIUS_BOTTOM * RADIUS_TOP + RADIUS_TOP**2)"}
